// Some portions generated by Codex

// @ts-check
const { test, expect } = require('@playwright/test');
const fs = require('node:fs');
const path = require('node:path');
const { createServer } = require('./workbench-preview-scroll-fixture.cjs');

let fixture;
let baseUrl;

async function focusByKeyboard(page, target) {
    const tabStops = await page.locator('a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), '
        + 'select:not([disabled]), textarea:not([disabled]), summary, [tabindex]:not([tabindex="-1"])').count();
    for (let index = 0; index < tabStops; index++) {
        await page.keyboard.press('Tab');
        if (await target.evaluate(element => document.activeElement === element)) {
            return;
        }
    }
    throw new Error('The preview scroll region was not reachable through keyboard tab navigation.');
}

test.beforeAll(async () => {
    fixture = createServer();
    await new Promise((resolve, reject) => {
        fixture.once('error', reject);
        fixture.listen(0, '127.0.0.1', resolve);
    });
    const address = fixture.address();
    if (!address || typeof address === 'string') {
        throw new Error('The preview fixture did not bind a TCP port.');
    }
    baseUrl = `http://127.0.0.1:${address.port}`;
});

test.afterAll(async () => {
    if (fixture && fixture.listening) {
        await new Promise((resolve, reject) => fixture.close(error => error ? reject(error) : resolve()));
    }
});

test('export and remove previews scroll wide RDF tables without widening the page', async ({ page }) => {
    const evidenceDirectory = process.env.WORKBENCH_PREVIEW_EVIDENCE;
    if (evidenceDirectory) {
        fs.mkdirSync(evidenceDirectory, { recursive: true });
    }

    for (const [viewId, width] of [['export', 1280], ['export', 390], ['remove', 1280], ['remove', 390]]) {
        await page.setViewportSize({ width, height: 820 });
        await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/${viewId}`, { waitUntil: 'networkidle' });
        if (viewId === 'export') {
            await expect(page.locator('#export-results table.data tbody tr')).toHaveCount(1);
        } else {
            const form = page.locator('#remove-form');
            await form.locator('#subj').fill('<urn:subject:' + 's'.repeat(180) + '>');
            await expect(form.locator('#remove-count')).toHaveText('1 statement matches');
            await form.locator('#remove-preview-button').click();
            await expect(page.locator('#remove-preview table.data tbody tr')).toHaveCount(1);
        }

        const section = viewId === 'export' ? '#export-results' : '#remove-preview';
        const metrics = await page.locator(`${section} table.data`).evaluate(table => {
            const wrapper = table.closest('.workbench-preview-table-scroll');
            const scrollport = wrapper || table.parentElement;
            const tableHead = table.querySelector('thead');
            const lastCell = table.querySelector('tbody tr:last-child td:last-child');
            if (scrollport) {
                scrollport.scrollLeft = scrollport.scrollWidth;
            }
            const scrollRect = scrollport.getBoundingClientRect();
            const lastCellRect = lastCell.getBoundingClientRect();
            return {
                wrapper: !!wrapper,
                tabindex: wrapper && wrapper.getAttribute('tabindex'),
                clientWidth: scrollport.clientWidth,
                scrollWidth: scrollport.scrollWidth,
                scrollLeft: scrollport.scrollLeft,
                viewportWidth: document.documentElement.clientWidth,
                documentWidth: document.documentElement.scrollWidth,
                headerHeight: tableHead.getBoundingClientRect().height,
                headerRowDisplay: getComputedStyle(tableHead.querySelector('tr')).display,
                lastCellRight: lastCellRect.right,
                scrollportRight: scrollRect.right,
                lastCellText: lastCell.textContent
            };
        });
        console.log(`PREVIEW_SCROLL ${viewId} ${width}px ${JSON.stringify(metrics)}`);
        expect.soft(metrics.wrapper, `${viewId} ${width}px preview has a dedicated scroll region`).toBe(true);
        expect.soft(metrics.tabindex, `${viewId} ${width}px preview scroll region is keyboard focusable`).toBe('0');
        expect.soft(metrics.scrollWidth, `${viewId} ${width}px preview is wider than its scroll region`)
            .toBeGreaterThan(metrics.clientWidth + 1);
        expect.soft(metrics.headerHeight, `${viewId} ${width}px four-column table header stays visible`).toBeGreaterThan(0);
        expect.soft(metrics.documentWidth, `${viewId} ${width}px preview does not widen the document`)
            .toBeLessThanOrEqual(metrics.viewportWidth + 1);
        expect.soft(metrics.scrollLeft, `${viewId} ${width}px preview can reach its right edge`)
            .toBeGreaterThan(0);
        expect.soft(metrics.lastCellRight, `${viewId} ${width}px last cell is reachable at the right edge`)
            .toBeLessThanOrEqual(metrics.scrollportRight + 1);
        expect.soft(metrics.lastCellText, `${viewId} ${width}px preserves the final graph value`).toContain('urn:graph:');

        const wrapper = page.locator(`${section} .workbench-preview-table-scroll`);
        if (await wrapper.count()) {
            await focusByKeyboard(page, wrapper);
            await expect.soft(wrapper, `${viewId} ${width}px preview region receives keyboard focus`).toBeFocused();
            await wrapper.evaluate(element => { element.scrollLeft = 0; });
            await page.keyboard.press('ArrowRight');
            const outlineStyle = await wrapper.evaluate(element => getComputedStyle(element).outlineStyle);
            expect.soft(outlineStyle, `${viewId} ${width}px keyboard focus remains visible`).not.toBe('none');
            await expect.poll(() => wrapper.evaluate(element => element.scrollLeft),
                { message: `${viewId} ${width}px ArrowRight scrolls the focused preview` }).toBeGreaterThan(0);
        }
        if (evidenceDirectory) {
            await page.screenshot({ path: path.join(evidenceDirectory, `${viewId}-${width}.png`), fullPage: true });
        }
    }
});

test('short four-column previews do not force horizontal scrolling', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 820 });

    for (const viewId of ['export', 'remove']) {
        if (viewId === 'export') {
            await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/export?fixture-preview=short`,
                { waitUntil: 'networkidle' });
            await expect(page.locator('#export-results table.data tbody tr')).toHaveCount(1);
        } else {
            await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/remove`, { waitUntil: 'networkidle' });
            const form = page.locator('#remove-form');
            await form.locator('#subj').fill('<urn:s>');
            await expect(form.locator('#remove-count')).toHaveText('1 statement matches');
            await form.locator('#remove-preview-button').click();
            await expect(page.locator('#remove-preview table.data tbody tr')).toHaveCount(1);
        }

        const section = viewId === 'export' ? '#export-results' : '#remove-preview';
        const metrics = await page.locator(`${section} table.data`).evaluate(table => {
            const scrollport = table.closest('.workbench-preview-table-scroll');
            return {
                headerCount: table.querySelectorAll('thead th').length,
                clientWidth: scrollport.clientWidth,
                scrollWidth: scrollport.scrollWidth
            };
        });
        console.log(`PREVIEW_SHORT ${viewId} ${JSON.stringify(metrics)}`);
        expect(metrics.headerCount, `${viewId} short preview keeps four statement columns`).toBe(4);
        expect(metrics.scrollWidth, `${viewId} short preview does not force horizontal scrolling`)
            .toBeLessThanOrEqual(metrics.clientWidth + 1);
    }
});
